    margin-bottom: 0.75rem;
}

::deep .modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio Group */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

::deep .radio-item input[type="radio"] {
