::deep .preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

::deep .preview-area h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

::deep .preview-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-top: 1rem;
}

::deep .preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #424242;
}

::deep .preview-theme-dark .preview-card {
    background: #2d2d2d;
    border-color: #424242;
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-theme-system {
    background: #fafafa;
    color: #333;
}

::deep .preview-font-small {
    font-size: 0.85rem;
}

::deep .preview-font-medium {
    font-size: 1rem;
}

::deep .preview-font-large {
    font-size: 1.15rem;
}

::deep .preview-compact {
    padding: 0.75rem;
}

::deep .preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

::deep .empty-state {
    color: #757575;
    font-style: italic;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}
