@namespace sv_45956b82e5224a68950cb1a1da052195.Components.Pages.Settings
@using sv_45956b82e5224a68950cb1a1da052195.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = &quot;Light&quot;" />
                        <span>Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = &quot;Dark&quot;" />
                        <span>Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = &quot;System&quot;" />
                        <span>System</span>
                    </label>
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="() => _fontSize = &quot;Small&quot;" />
                        <span>Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="() => _fontSize = &quot;Medium&quot;" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="() => _fontSize = &quot;Large&quot;" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
                    <button class="btn-primary">Sample Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@page "/settings"
@namespace sv_45956b82e5224a68950cb1a1da052195.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

::deep .settings-sidebar {
    width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

::deep .settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
    font-weight: 500;
}

::deep .settings-sidebar li:hover {
    background: #e9ecef;
}

::deep .settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
}

::deep .sidebar-icon {
    font-size: 1.2rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: #333;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus,
::deep .form-group select:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

::deep .form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.15s;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ced4da;
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.15s;
}

::deep .btn-secondary:hover {
    background: #e0e0e0;
}

::deep .btn-danger {
    background: #d32f2f;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

::deep .btn-danger:hover {
    background: #c62828;
}

::deep .btn-small {
    padding: 0.3rem 0.75rem;
    font-size: 0.85rem;
}

::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-weight: 500;
    animation: fadeIn 0.3s ease-in;
}

::deep .toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

::deep .error-message {
    color: #d32f2f;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

/* Avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

::deep .avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

::deep .avatar-url-display {
    font-size: 0.8rem;
    color: #757575;
    margin-top: 0.5rem;
    word-break: break-all;
}

/* Toggles */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #1976d2;
}

/* Channels */
::deep .channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .channel-list li {
    padding: 0.4rem 0;
}

::deep .muted-channels h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

/* Expandable Panel */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* TFA */
::deep .tfa-section {
    margin-bottom: 1.5rem;
}

::deep .tfa-status {
    display: flex;
    align-items: center;
    gap: 1rem;
}

::deep .status-indicator {
    font-size: 1.2rem;
}

::deep .status-on {
    color: #2e7d32;
}

::deep .status-off {
    color: #9e9e9e;
}

::deep .info-text {
    font-size: 0.85rem;
    color: #757575;
    margin-top: 0.5rem;
}

/* Sessions Table */
::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #616161;
}

::deep .current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    font-weight: 500;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
}

::deep .modal-dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

::deep .modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio Group */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

::deep .radio-item input[type="radio"] {
    accent-color: #1976d2;
}

/* Appearance Preview */
::deep .preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

::deep .preview-area h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

::deep .preview-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-top: 1rem;
}

::deep .preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #424242;
}

::deep .preview-theme-dark .preview-card {
    background: #2d2d2d;
    border-color: #424242;
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-theme-system {
    background: #fafafa;
    color: #333;
}

::deep .preview-font-small {
    font-size: 0.85rem;
}

::deep .preview-font-medium {
    font-size: 1rem;
}

::deep .preview-font-large {
    font-size: 1.15rem;
}

::deep .preview-compact {
    padding: 0.75rem;
}

::deep .preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

::deep .empty-state {
    color: #757575;
    font-style: italic;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

